// REQ-162 (docs/sims.md 16, 17 exit): engine major 1, the v1 corpus and the
// golden replays of every seeded scenario as ONE plain script, so Hermes and
// the three browsers run exactly the program Node runs. Each engine file is
// transpiled on its own (typescript's transpileModule: types erased, no type
// check, no new dependency) and wrapped in a tiny module table; the corpus
// cases and the documents travel as JSON. The script defines one global,
// simCrossRuntimeEngine(), whose text must be byte-identical everywhere.
import { readdirSync, readFileSync } from "node:fs";
import { basename, join } from "node:path";
import { runInNewContext } from "node:vm";
import ts from "typescript";
import { ALL_DOCUMENTS, loadDocument } from "../documents.ts";

const ENGINE_DIR = join(__dirname, "..", "engine", "v1");
const GOLDEN_DIR = join(ENGINE_DIR, "golden");

// The modules the runner needs, by file. Tests are left out; the corpus
// runner (golden/corpus.ts) is pure and goes in under its own name.
function engineFiles(): { name: string; path: string }[] {
  const files = readdirSync(ENGINE_DIR)
    .filter((f) => f.endsWith(".ts") && !f.endsWith(".test.ts"))
    .sort()
    .map((f) => ({ name: f, path: join(ENGINE_DIR, f) }));
  files.push({ name: "corpus.ts", path: join(GOLDEN_DIR, "corpus.ts") });
  return files;
}

function transpile(path: string): string {
  const out = ts.transpileModule(readFileSync(path, "utf8"), {
    fileName: path,
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2019,
      verbatimModuleSyntax: false,
      isolatedModules: true,
      removeComments: true,
      esModuleInterop: false,
    },
    reportDiagnostics: false,
  });
  return out.outputText.replace(/\/\/# sourceMappingURL=.*$/m, "");
}

export interface BundleData {
  corpus: unknown[];
  documents: { slug: string; doc: unknown; golden: unknown }[];
}

export function bundleData(): BundleData {
  const corpus = readdirSync(join(GOLDEN_DIR, "corpus"))
    .filter((f) => f.endsWith(".json"))
    .sort()
    .map((f) => JSON.parse(readFileSync(join(GOLDEN_DIR, "corpus", f), "utf8")));
  const documents = ALL_DOCUMENTS.map((e) => ({
    slug: `${e.course}/${e.slug}`,
    doc: loadDocument(e),
    golden: e.golden ? JSON.parse(readFileSync(e.golden, "utf8")) : null,
  }));
  return { corpus, documents };
}

// The runner, in plain ES2019. It prints one line per corpus case and per
// golden path, then a 32-bit FNV-1a over every line so a reader can compare
// two outputs at a glance. Failures are printed, not thrown: a runtime that
// disagrees should show where.
const RUNNER = `
function simCrossRuntimeEngine() {
  var corpus = __require("corpus.ts"), validate = __require("validate.ts"), engine = __require("engine.ts");
  var lines = [];
  for (var i = 0; i < __DATA.corpus.length; i++) {
    var c = __DATA.corpus[i], r;
    try { r = corpus.runCorpusCase(c); lines.push("case " + c.id + " hash=" + r.hash + " final=" + r.finalTick + " failures=" + r.failures.length + (r.failures.length ? " first=" + JSON.stringify(r.failures[0]) : "")); }
    catch (e) { lines.push("case " + c.id + " threw " + String(e && e.message)); }
  }
  for (var d = 0; d < __DATA.documents.length; d++) {
    var entry = __DATA.documents[d];
    if (!entry.golden) continue;
    for (var p = 0; p < entry.golden.paths.length; p++) {
      var path = entry.golden.paths[p];
      try {
        var g = validate.replayGoldenPath(entry.doc, path, function (run) { return engine.stateHash(run.state); });
        var db = g.debrief;
        lines.push("golden " + entry.slug + "/" + path.id + " hash=" + g.stateHash + " final=" + g.finalTick + " ending=" + db.ending + " class=" + db.outcomeClass + " rating=" + db.rating + " score=" + db.processScore + " mismatches=" + g.mismatches.length + (g.error ? " error=" + JSON.stringify(g.error) : ""));
      } catch (e) { lines.push("golden " + entry.slug + "/" + path.id + " threw " + String(e && e.message)); }
    }
  }
  var h = 0x811c9dc5, text = lines.join("\\n");
  for (var k = 0; k < text.length; k++) { h ^= text.charCodeAt(k); h = Math.imul(h, 0x01000193) >>> 0; }
  lines.push("engine " + engine.ENGINE_VERSION + " lines=" + (lines.length) + " hash: " + ("0000000" + h.toString(16)).slice(-8));
  return lines.join("\\n");
}
`;

export function engineBundleSource(data: BundleData = bundleData()): string {
  const mods = engineFiles()
    .map((f) => `__def(${JSON.stringify(f.name)}, function (exports, require, module) {\n${transpile(f.path)}\n});`)
    .join("\n");
  return `// Generated by backend/lib/sim/cross-runtime/engine-bundle.ts (REQ-162). Do not edit.
var __mods = {}, __cache = {};
function __def(name, fn) { __mods[name] = fn; }
function __require(spec) {
  var name = spec.slice(spec.lastIndexOf("/") + 1);
  if (__cache[name]) return __cache[name].exports;
  if (!__mods[name]) throw new Error("cross-runtime bundle: no module " + spec);
  var module = { exports: {} };
  __cache[name] = module;
  __mods[name](module.exports, __require, module);
  return module.exports;
}
${mods}
var __DATA = ${JSON.stringify(data)};
${RUNNER}
`;
}

export function runEngineBundleInNode(source: string = engineBundleSource()): string {
  const sandbox = {} as { simCrossRuntimeEngine: () => string };
  runInNewContext(source, sandbox, { filename: "sim-engine-bundle.js" });
  return `${sandbox.simCrossRuntimeEngine()}\n`;
}

export function engineHermesScript(source: string = engineBundleSource()): string {
  return `${source}\nprint(simCrossRuntimeEngine());\n`;
}

export const BUNDLE_MODULES = (): string[] => engineFiles().map((f) => basename(f.path));
